function annualFuel(rate,p,power,load,hours,units,manualUnit){
 if(!Number.isFinite(rate)||!p)return null;
 if(p.mode==='specific_mj')return {qty:rate*(power*load/100)*hours*units,unit:'МДж'};
 if(p.mode==='thermal_kw')return {qty:rate*hours*units,unit:'кВт·ч тепла'};
 if(p.mode==='manual'){const unit=(manualUnit||'ед./ч').trim().replace(/\s*\/\s*(ч|h)$/i,'').trim();return {qty:rate*hours*units,unit};}
 if(p.mode==='flow'){if(/scfm/i.test(p.source_unit||''))return {qty:rate*60*hours*units,unit:'стандартный куб. фут'};return {qty:rate*hours*units,unit:(p.unit||'ед./ч').replace(/\/ч/g,'').trim()};}
 return null;
}
function avgFactor(percent,years){const r=percent/100;if(!Number.isFinite(r)||r<=-1||!Number.isInteger(years)||years<1)return NaN;if(Math.abs(r)<1e-12)return 1;return (((1+r)**years)-1)/(years*r);}

// Hybrid-only functions. The copied legacy catalog and annualFuel() above stay unchanged.
function parseHybridCsv(text) {
  const lines = String(text).replace(/^\uFEFF/, '').split(/\r?\n/);
  while (lines.length && lines[lines.length - 1] === '') lines.pop();
  if (!lines.length || !lines[0].trim()) throw new Error('CSV пустой: отсутствует строка заголовков.');
  const delimiter = lines[0].includes(';') ? ';' : ',';
  const headers = lines[0].split(delimiter).map(value => value.trim().toLowerCase());
  if (headers.some(value => !value)) throw new Error('В заголовке CSV есть пустое имя столбца.');
  if (headers.some(value => !['load_kw', 'pv_kw'].includes(value))) throw new Error('Допустимы только столбцы load_kw и pv_kw.');
  if (new Set(headers).size !== headers.length) throw new Error('В заголовке CSV есть повторяющиеся столбцы.');
  const loadIndex = headers.indexOf('load_kw');
  const pvIndex = headers.indexOf('pv_kw');
  if (loadIndex < 0) throw new Error('В CSV нужен столбец load_kw.');
  const rows = [];
  for (let index = 1; index < lines.length; index++) {
    const lineNumber = index + 1;
    const line = lines[index];
    if (!line.trim()) throw new Error(`Пустая строка CSV: ${lineNumber}.`);
    const cells = line.split(delimiter);
    if (cells.length !== headers.length) throw new Error(`В строке ${lineNumber} ${cells.length} столбцов; в заголовке ${headers.length}.`);
    const parseCell = (cell, label) => {
      if (cell.trim() === '') throw new Error(`Пустое значение ${label} в строке ${lineNumber}.`);
      const normalized = delimiter === ';' ? cell.trim().replace(',', '.') : cell.trim();
      const value = Number(normalized);
      if (!Number.isFinite(value)) throw new Error(`Значение ${label} в строке ${lineNumber} должно быть конечным числом.`);
      if (value < 0) throw new Error(`Значение ${label} в строке ${lineNumber} не может быть отрицательным.`);
      return value;
    };
    const load = parseCell(cells[loadIndex], 'load_kw');
    const pv = pvIndex < 0 ? 0 : parseCell(cells[pvIndex], 'pv_kw');
    rows.push({ load, pv });
  }
  if (rows.length !== 8760) throw new Error(`Нужно 8 760 часовых строк; найдено ${rows.length}.`);
  return { rows, hasPvColumn: pvIndex >= 0 };
}

function hybridProfilePolicy(profile) {
  if (!profile) return { eligible: false, reason: 'Пользовательский ввод; источник не приложен и данные не подтверждены.' };
  const supportedMode = ['specific_mj', 'flow'].includes(profile.mode);
  const confirmed = ['OEM подтверждено', 'OEM confirmed'].includes(profile.status);
  const eligible = profile.freq === '60' && confirmed && supportedMode && profile.samples?.['100'] !== undefined;
  const reason = eligible ? '60 Hz; OEM-профиль подтверждён.' : `Только справка: частота ${profile.freq || 'не указана'}, статус «${profile.status || 'не указан'}»; в расчёте Texas профиль заблокирован.`;
  return { eligible, reason };
}

function hybridFuelUnit(config) {
  if (config.profile?.mode === 'specific_mj') return 'МДж';
  if (config.profile?.mode === 'flow' && /scfm/i.test(config.profile.source_unit || '')) return 'стандартный кубический фут';
  if (config.profile?.mode === 'flow') return (config.profile.unit || 'ед./ч').replace(/\/ч/g, '').trim();
  return String(config.manualFuelUnit || '').trim();
}

// Returns fuel quantity for one hourly interval. Profile flow and scfm are converted once.
function hybridFuelForHour(config, outputKW) {
  if (outputKW <= 0) return { quantity: 0, unit: hybridFuelUnit(config) };
  const power = Number(config.enginePowerKW);
  const unit = hybridFuelUnit(config);
  const rate = Number(config.rawFuelRate);
  if (!Number.isFinite(rate) || rate <= 0) throw new Error('Расход топлива должен быть строго положительным для работающей ГПУ.');
  if (!unit) throw new Error('Укажите единицу топлива для расчёта тарифа и расхода.');
  if (!Number.isFinite(power) || power <= 0 || !Number.isFinite(Number(config.units)) || config.units <= 0) throw new Error('Проверьте номинальную мощность и количество двигателей.');
  if (config.profile && ['specific_mj', 'flow'].includes(config.profile.mode)) {
    const curve = Object.entries(config.profile.samples || {})
      .map(([load, value]) => ({ load: Number(load), value: Number(value) }))
      .filter(point => Number.isFinite(point.load) && point.load > 0 && point.load <= 100 && Number.isFinite(point.value) && point.value > 0)
      .sort((a, b) => a.load - b.load);
    const actualLoad = outputKW / (power * config.units) * 100;
    if (curve.length < 1 || actualLoad < curve[0].load - 1e-9 || actualLoad > curve[curve.length - 1].load + 1e-9) {
      const range = curve.length ? `${curve[0].load}–${curve[curve.length - 1].load}%` : 'отсутствуют';
      throw new Error(`Фактическая загрузка ГПУ ${actualLoad.toFixed(1)}% вне подтверждённых точек профиля (${range}); экстраполяция отключена.`);
    }
    let pointRate;
    const exact = curve.find(point => Math.abs(point.load - actualLoad) < 1e-9);
    if (exact) pointRate = exact.value;
    else {
      let upperIndex = curve.findIndex(point => point.load > actualLoad);
      if (upperIndex <= 0) throw new Error('Не удалось определить точки интерполяции расхода топлива.');
      const low = curve[upperIndex - 1], high = curve[upperIndex];
      const share = (actualLoad - low.load) / (high.load - low.load);
      pointRate = low.value + share * (high.value - low.value);
    }
    if (config.profile.mode === 'specific_mj') return { quantity: pointRate * outputKW, unit: 'МДж' };
    const hourlyFlow = /scfm/i.test(config.profile.source_unit || '') ? pointRate * 60 : pointRate;
    return { quantity: hourlyFlow * config.units, unit };
  }
  // Manual input is explicitly defined at 100% load for one engine per hour.
  return { quantity: rate * outputKW / power, unit };
}

function simulateHybridScenario(rows, scenario, config) {
  if (!scenario || !['grid', 'gas', 'pv', 'bess'].every(key => typeof scenario[key] === 'boolean')) throw new Error('Сценарий должен явно задавать признаки grid, gas, pv и bess.');
  const c = config;
  const positive = ['enginePowerKW', 'units', 'bessPowerKW', 'bessEnergyKWh', 'rte', 'initialSocPercent', 'reserveSocPercent'];
  for (const key of positive) if (!Number.isFinite(Number(c[key])) || Number(c[key]) < 0) throw new Error(`Проверьте числовой параметр ${key}.`);
  if (scenario.gas && c.enginePowerKW > 0 && c.units > 0 && Number(c.frequencyHz) !== 60) throw new Error('Для проекта Texas разрешены только рейтинги 60 Hz.');
  if (scenario.gas && c.enginePowerKW > 0 && c.units > 0 && (!Number.isFinite(Number(c.rawFuelRate)) || Number(c.rawFuelRate) <= 0)) throw new Error('Расход топлива работающей ГПУ должен быть строго положительным.');
  if (scenario.gas && c.enginePowerKW > 0 && c.units > 0 && c.fuelPriceInput !== true) throw new Error('Введите тариф топлива явно; нулевой тариф допустим как явный ввод.');
  if (scenario.gas && c.enginePowerKW > 0 && c.units > 0 && (!Number.isFinite(Number(c.fuelPrice)) || Number(c.fuelPrice) < 0)) throw new Error('Тариф топлива должен быть конечным и неотрицательным.');
  if (scenario.grid && c.gridPriceInput !== true) throw new Error('Введите тариф импорта сети явно; нулевой тариф допустим как явный ввод.');
  if (scenario.grid && (!Number.isFinite(Number(c.gridPrice)) || Number(c.gridPrice) < 0)) throw new Error('Тариф импорта сети должен быть конечным и неотрицательным.');
  if (c.units > 100 || !Number.isInteger(c.units)) throw new Error('Количество двигателей должно быть целым числом от 0 до 100.');
  if (c.rte <= 0 || c.rte > 1 || c.initialSocPercent > 100 || c.reserveSocPercent > c.initialSocPercent || c.reserveSocPercent > 100) throw new Error('Проверьте КПД и пределы SOC батареи.');
  const startSoc = c.bessEnergyKWh * c.initialSocPercent / 100;
  const reserve = c.bessEnergyKWh * c.reserveSocPercent / 100;
  let soc = startSoc, gridImport = 0, gasGeneration = 0, pvUsed = 0, pvCurtailment = 0;
  let bessCharge = 0, bessDischarge = 0, unserved = 0, fuelQuantity = 0, balanceResidual = 0;
  const eta = Math.sqrt(c.rte);
  for (let hour = 0; hour < rows.length; hour++) {
    const load = rows[hour].load;
    const pv = scenario.pv ? rows[hour].pv : 0;
    let residualLoad = load;
    let chargeThisHour = 0, dischargeThisHour = 0, gasThisHour = 0, gridThisHour = 0;
    const pvToLoad = Math.min(residualLoad, pv);
    residualLoad -= pvToLoad;
    pvUsed += pvToLoad;
    const pvSurplus = pv - pvToLoad;
    if (scenario.bess && pvSurplus > 0) {
      chargeThisHour = Math.min(pvSurplus, c.bessPowerKW, (c.bessEnergyKWh - soc) / eta);
      soc += chargeThisHour * eta;
      bessCharge += chargeThisHour;
    }
    const curtailThisHour = Math.max(0, pvSurplus - chargeThisHour);
    pvCurtailment += curtailThisHour;
    if (scenario.bess && residualLoad > 0) {
      dischargeThisHour = Math.max(0, Math.min(residualLoad, c.bessPowerKW, (soc - reserve) * eta));
      soc -= dischargeThisHour / eta;
      residualLoad -= dischargeThisHour;
      bessDischarge += dischargeThisHour;
    }
    if (scenario.gas && c.enginePowerKW > 0 && c.units > 0) {
      gasThisHour = Math.min(residualLoad, c.enginePowerKW * c.units);
      residualLoad -= gasThisHour;
      if (scenario.bess && soc < c.bessEnergyKWh) {
        const unusedGasCapacity = c.enginePowerKW * c.units - gasThisHour;
        // One bidirectional PCS cannot charge and discharge in the same hourly interval.
        // PV and gas share the same charge-power limit for this interval.
        const remainingChargePower = dischargeThisHour > 1e-9
          ? 0
          : Math.max(0, c.bessPowerKW - chargeThisHour);
        const gasCharge = Math.min(unusedGasCapacity, remainingChargePower, (c.bessEnergyKWh - soc) / eta);
        if (gasCharge > 0) {
          gasThisHour += gasCharge;
          soc += gasCharge * eta;
          chargeThisHour += gasCharge;
          bessCharge += gasCharge;
        }
      }
      gasGeneration += gasThisHour;
      if (gasThisHour > 0) {
        const fuel = hybridFuelForHour(c, gasThisHour);
        fuelQuantity += fuel.quantity;
      }
    }
    if (scenario.grid) {
      gridThisHour = residualLoad;
      gridImport += gridThisHour;
      residualLoad = 0;
    }
    unserved += residualLoad;
    const sourcesPlusUnserved = pv + dischargeThisHour + gasThisHour + gridThisHour + residualLoad;
    const usesPlusCurtailment = load + chargeThisHour + curtailThisHour;
    balanceResidual += Math.abs(sourcesPlusUnserved - usesPlusCurtailment);
    if (soc < reserve - 1e-7 || soc > c.bessEnergyKWh + 1e-7) throw new Error(`SOC вышел за пределы в часовом интервале ${hour + 1}.`);
  }
  const cost = (gridImport > 0 ? gridImport * Number(c.gridPrice) : 0) + (fuelQuantity > 0 ? fuelQuantity * Number(c.fuelPrice) : 0);
  const socClosed = Math.abs(soc - startSoc) <= Math.max(1e-6, c.bessEnergyKWh * 1e-6);
  return {
    scenario, gridImportKWh: gridImport, gasGenerationKWh: gasGeneration, pvUsedKWh: pvUsed,
    pvCurtailmentKWh: pvCurtailment, bessChargeKWh: bessCharge, bessDischargeKWh: bessDischarge,
    unservedKWh: unserved, fuelQuantity, fuelUnit: hybridFuelUnit(c), cost,
    startSocKWh: startSoc, endSocKWh: soc, startSocPercent: c.initialSocPercent,
    endSocPercent: c.bessEnergyKWh > 0 ? soc / c.bessEnergyKWh * 100 : 0,
    usableEnergyRemainingKWh: Math.max(0, soc - reserve), balanceResidualKWh: balanceResidual,
    socClosed, costComparable: socClosed, costComparisonNote: socClosed ? 'Конечный SOC совпадает с начальным.' : 'Не сравнивать затраты напрямую: конечный SOC отличается от начального; начальная энергия не восстановлена.'
  };
}

globalThis.K4Hybrid = { parseHybridCsv, hybridProfilePolicy, hybridFuelUnit, hybridFuelForHour, simulateHybridScenario };
